package aiff

import "fmt"

// G.711 μ-law companding, as used by the AIFC "ulaw" and "ULAW" compression
// types.
//
// 8 bit μ-law code words are decoded to 16 bit signed linear PCM values in the
// [-32124, 32124] range, which is the representation the rest of the package
// uses for decoded audio. Encoding accepts 16 bit signed linear PCM values and
// produces 8 bit code words.
//
// The tables are built from the reference G.711 algorithm (ITU-T G.711, see
// also the tables generated by libavcodec's build_xlaw_table) so that
// decoding matches libsndfile/ffmpeg byte for byte and encoding picks the same
// code word as those implementations.

const (
	// ulawBias is the G.711 quantization bias.
	ulawBias = 0x84
)

// ulawDecodeTable maps an 8 bit μ-law code word to its 16 bit linear value.
var ulawDecodeTable = func() [256]int16 {
	var table [256]int16
	for i := range table {
		table[i] = int16(ulaw2linear(uint8(i)))
	}
	return table
}()

// ulaw2linear implements the G.711 μ-law expansion of a single code word.
func ulaw2linear(u uint8) int {
	// Complement to obtain the normal μ-law value.
	u = ^u
	// Extract and bias the quantization bits, then shift by the segment
	// number and subtract the bias.
	t := ((int(u&0x0F) << 3) + ulawBias) << ((u & 0x70) >> 4)
	if u&0x80 != 0 {
		return ulawBias - t
	}
	return t - ulawBias
}

// ulawEncodeTable maps a sample shifted right by 2 and offset by 32768 (so
// that it ranges over [0, 16384)) to its μ-law code word. It is built from the
// decoding table using the same midpoint rounding as the reference G.711
// encoders.
var ulawEncodeTable = func() [16384]uint8 {
	var table [16384]uint8

	const mask = 0xFF
	j := 1
	table[8192] = mask
	for i := 0; i < 127; i++ {
		v1 := ulaw2linear(uint8(i) ^ mask)
		v2 := ulaw2linear(uint8(i+1) ^ mask)
		v := (v1 + v2 + 4) >> 3
		for ; j < v; j++ {
			table[8192-j] = uint8(i) ^ mask ^ 0x80
			table[8192+j] = uint8(i) ^ mask
		}
	}
	for ; j < 8192; j++ {
		table[8192-j] = 127 ^ mask ^ 0x80
		table[8192+j] = 127 ^ mask
	}
	// The most negative value maps to the same code word as its successor.
	table[0] = table[1]

	return table
}()

// ulawDecodeSample decodes an 8 bit μ-law code word into 16 bit linear PCM.
func ulawDecodeSample(b byte) int {
	return int(ulawDecodeTable[b])
}

// ulawEncodeSample encodes a 16 bit signed linear PCM sample into an 8 bit
// μ-law code word. Values outside of the 16 bit signed range are clamped.
func ulawEncodeSample(sample int) byte {
	if sample > 32767 {
		sample = 32767
	} else if sample < -32768 {
		sample = -32768
	}
	return ulawEncodeTable[(sample+32768)>>2]
}

// DecodeULaw expands 8 bit G.711 μ-law code words into 16 bit signed linear
// PCM samples, one value per code word. The code words are interpreted in
// order, so interleaved stereo stays interleaved.
func DecodeULaw(codeWords []byte) []int {
	out := make([]int, len(codeWords))
	for i, b := range codeWords {
		out[i] = ulawDecodeSample(b)
	}
	return out
}

// EncodeULaw compresses 16 bit signed linear PCM samples into 8 bit G.711
// μ-law code words. Samples are compressed in order, so interleaved stereo
// stays interleaved. Values outside of the 16 bit signed range are rejected
// with an ErrInvalidSample wrapped error rather than clamped.
func EncodeULaw(samples []int) ([]byte, error) {
	out := make([]byte, len(samples))
	for i, s := range samples {
		if s < -32768 || s > 32767 {
			return nil, fmt.Errorf("%w: %d can't be encoded as G.711, samples must be 16 bit signed PCM", ErrInvalidSample, s)
		}
		out[i] = ulawEncodeSample(s)
	}
	return out, nil
}
